package com.highpass.runspot.chat.outbox;import com.fasterxml.jackson.databind.*;import com.highpass.runspot.chat.config.RabbitMqConfig;import lombok.RequiredArgsConstructor;import org.springframework.amqp.rabbit.annotation.RabbitListener;import org.springframework.messaging.simp.SimpMessagingTemplate;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;
@Component @RequiredArgsConstructor public class ChatBrokerConsumer{private final ObjectMapper mapper;private final ChatInboxRepository inbox;private final SimpMessagingTemplate messaging;
 @RabbitListener(queues=RabbitMqConfig.QUEUE)@Transactional public void consume(String raw)throws Exception{ChatBrokerEvent event=mapper.readValue(raw,ChatBrokerEvent.class);if(inbox.existsByEventId(event.eventId()))return;inbox.saveAndFlush(ChatInbox.received(event.eventId()));JsonNode payload=mapper.readTree(event.payload());messaging.convertAndSend(event.destination(),payload);}}
